  "how.content1": "How Omnia-Mundi works: participants, trade chains, transparent pricing and profit distribution.",
  "how.title1": "How it works — Omnia-Mundi",
  "how.a1": "Skip to content",
  "how.arialabel1": "Omnia-Mundi — home",
  "how.span1": "Search products in the catalog",
